export type RegenerationEnable = boolean | 0 | 1 | number;

export interface BrakeAllocationInputs {
  brakeDemand: number;
  vehicleMassKg: number;
  vehicleSpeedKph: number;
  batterySocPct: number;
  batteryTempC: number;
  batteryVoltageV: number;
  chargeCurrentLimitA: number;
  chargePowerLimitKw: number;
  motorRegenTorqueLimitNm: number;
  motorRegenPowerLimitKw: number;
  regenEnabled: RegenerationEnable;
}

export interface BrakeAllocationCalibration {
  maxServiceDecelMps2: number;
  wheelRadiusM: number;
  gearRatio: number;
  drivetrainEfficiency: number;
  regenEfficiency: number;
  speedCutoffMps: number;
  fullRegenSpeedMps: number;
  socDeratePct: number;
  socStopPct: number;
  coldCutoffC: number;
  coldFullC: number;
  hotFullC: number;
  hotCutoffC: number;
  minimumSpeedMps: number;
  forceEpsilonN: number;
}

export type ActiveLimitCode =
  | "NO_BRAKING"
  | "REGEN_DISABLED"
  | "LOW_SPEED"
  | "DRIVER_DEMAND"
  | "MOTOR_TORQUE"
  | "MOTOR_POWER"
  | "BATTERY_SOC"
  | "BATTERY_TEMPERATURE"
  | "BATTERY_CURRENT"
  | "BATTERY_POWER"
  | "BATTERY_ACCEPTANCE";

export interface BrakeAllocationResult {
  requestedDecelerationMps2: number;
  requestedForceN: number;
  requestedWheelTorqueNm: number;
  vehicleSpeedMps: number;
  wheelSpeedRpm: number;
  motorSpeedRpm: number;
  speedFactor: number;
  socFactor: number;
  temperatureFactor: number;
  currentDerivedChargePowerKw: number;
  baseChargePowerKw: number;
  allowedBatteryPowerKw: number;
  torqueForceLimitN: number;
  powerForceLimitN: number;
  batteryForceLimitN: number;
  regenerativeForceN: number;
  frictionForceN: number;
  regenerativeWheelTorqueNm: number;
  frictionWheelTorqueNm: number;
  mechanicalRegenPowerKw: number;
  batteryChargePowerKw: number;
  regenerativeCurrentA: number;
  regenerativePercent: number;
  frictionPercent: number;
  forceBalanceResidualN: number;
  activeLimitCode: ActiveLimitCode;
  activeLimitLabel: string;
  warnings: string[];
  visual: {
    stopTimeEstimateS: number;
    stopDistanceEstimateM: number;
    animationDurationS: number;
    regenIntensity01: number;
    frictionHeatIntensity01: number;
    batteryChargeIntensity01: number;
  };
}

export const DEFAULT_BRAKE_INPUTS: BrakeAllocationInputs = {
  brakeDemand: 0.4,
  vehicleMassKg: 1500,
  vehicleSpeedKph: 60,
  batterySocPct: 50,
  batteryTempC: 25,
  batteryVoltageV: 350,
  chargeCurrentLimitA: 120,
  chargePowerLimitKw: 45,
  motorRegenTorqueLimitNm: 180,
  motorRegenPowerLimitKw: 50,
  regenEnabled: true,
};

export const DEFAULT_BRAKE_CALIBRATION: BrakeAllocationCalibration = {
  maxServiceDecelMps2: 3.5,
  wheelRadiusM: 0.31,
  gearRatio: 9,
  drivetrainEfficiency: 0.92,
  regenEfficiency: 0.88,
  speedCutoffMps: 2,
  fullRegenSpeedMps: 5,
  socDeratePct: 80,
  socStopPct: 95,
  coldCutoffC: -5,
  coldFullC: 15,
  hotFullC: 40,
  hotCutoffC: 55,
  minimumSpeedMps: 0.1,
  forceEpsilonN: 1,
};

const clamp = (value: number, minimum: number, maximum: number): number =>
  Math.min(maximum, Math.max(minimum, value));

const assertFinite = (name: string, value: number): void => {
  if (!Number.isFinite(value)) {
    throw new Error(`${name} must be a finite number.`);
  }
};

const warnOutside = (
  warnings: string[],
  name: string,
  value: number,
  minimum: number,
  maximum: number,
  unit: string,
): void => {
  if (value < minimum || value > maximum) {
    warnings.push(`${name} is outside the suggested educational range ${minimum}-${maximum} ${unit}.`);
  }
};

export function calculateBrakeAllocation(
  rawInputs: BrakeAllocationInputs,
  calibration: BrakeAllocationCalibration = DEFAULT_BRAKE_CALIBRATION,
): BrakeAllocationResult {
  const numericEntries: Array<[string, number]> = [
    ["brakeDemand", rawInputs.brakeDemand],
    ["vehicleMassKg", rawInputs.vehicleMassKg],
    ["vehicleSpeedKph", rawInputs.vehicleSpeedKph],
    ["batterySocPct", rawInputs.batterySocPct],
    ["batteryTempC", rawInputs.batteryTempC],
    ["batteryVoltageV", rawInputs.batteryVoltageV],
    ["chargeCurrentLimitA", rawInputs.chargeCurrentLimitA],
    ["chargePowerLimitKw", rawInputs.chargePowerLimitKw],
    ["motorRegenTorqueLimitNm", rawInputs.motorRegenTorqueLimitNm],
    ["motorRegenPowerLimitKw", rawInputs.motorRegenPowerLimitKw],
  ];
  numericEntries.forEach(([name, value]) => assertFinite(name, value));

  if (rawInputs.vehicleMassKg <= 0) throw new Error("vehicleMassKg must be greater than zero.");
  if (rawInputs.batteryVoltageV <= 0) throw new Error("batteryVoltageV must be greater than zero.");
  if (rawInputs.chargeCurrentLimitA < 0) throw new Error("chargeCurrentLimitA cannot be negative.");
  if (rawInputs.chargePowerLimitKw < 0) throw new Error("chargePowerLimitKw cannot be negative.");
  if (rawInputs.motorRegenTorqueLimitNm < 0) throw new Error("motorRegenTorqueLimitNm cannot be negative.");
  if (rawInputs.motorRegenPowerLimitKw < 0) throw new Error("motorRegenPowerLimitKw cannot be negative.");
  if (calibration.wheelRadiusM <= 0) throw new Error("wheelRadiusM must be greater than zero.");
  if (calibration.gearRatio <= 0) throw new Error("gearRatio must be greater than zero.");
  if (calibration.regenEfficiency <= 0 || calibration.regenEfficiency > 1) {
    throw new Error("regenEfficiency must be greater than zero and no more than one.");
  }

  const warnings: string[] = [];
  warnOutside(warnings, "Brake demand", rawInputs.brakeDemand, 0, 1, "-");
  warnOutside(warnings, "Vehicle mass", rawInputs.vehicleMassKg, 800, 3500, "kg");
  warnOutside(warnings, "Vehicle speed", rawInputs.vehicleSpeedKph, 0, 160, "km/h");
  warnOutside(warnings, "Battery SOC", rawInputs.batterySocPct, 0, 100, "%");
  warnOutside(warnings, "Battery temperature", rawInputs.batteryTempC, -15, 65, "degC");
  warnOutside(warnings, "Battery voltage", rawInputs.batteryVoltageV, 200, 800, "V");
  warnOutside(warnings, "Charge-current limit", rawInputs.chargeCurrentLimitA, 20, 400, "A");
  warnOutside(warnings, "Charge-power limit", rawInputs.chargePowerLimitKw, 5, 200, "kW");
  warnOutside(warnings, "Motor regenerative-torque limit", rawInputs.motorRegenTorqueLimitNm, 20, 500, "N m");
  warnOutside(warnings, "Motor regenerative-power limit", rawInputs.motorRegenPowerLimitKw, 5, 250, "kW");

  const brakeDemand = clamp(rawInputs.brakeDemand, 0, 1);
  const vehicleSpeedKph = Math.max(0, rawInputs.vehicleSpeedKph);
  const batterySocPct = clamp(rawInputs.batterySocPct, 0, 100);
  const enableFactor = typeof rawInputs.regenEnabled === "boolean"
    ? (rawInputs.regenEnabled ? 1 : 0)
    : clamp(rawInputs.regenEnabled, 0, 1);

  const vehicleSpeedMps = vehicleSpeedKph / 3.6;
  const safeSpeedMps = Math.max(vehicleSpeedMps, calibration.minimumSpeedMps);

  const requestedDecelerationMps2 = brakeDemand * calibration.maxServiceDecelMps2;
  const requestedForceN = rawInputs.vehicleMassKg * requestedDecelerationMps2;
  const requestedWheelTorqueNm = requestedForceN * calibration.wheelRadiusM;

  const wheelAngularSpeedRadS = vehicleSpeedMps / calibration.wheelRadiusM;
  const wheelSpeedRpm = wheelAngularSpeedRadS * 60 / (2 * Math.PI);
  const motorAngularSpeedRadS = wheelAngularSpeedRadS * calibration.gearRatio;
  const motorSpeedRpm = motorAngularSpeedRadS * 60 / (2 * Math.PI);

  const speedFactor = clamp(
    (vehicleSpeedMps - calibration.speedCutoffMps)
      / (calibration.fullRegenSpeedMps - calibration.speedCutoffMps),
    0,
    1,
  );

  const torqueForceLimitN = speedFactor
    * rawInputs.motorRegenTorqueLimitNm
    * calibration.gearRatio
    * calibration.drivetrainEfficiency
    / calibration.wheelRadiusM;

  const powerForceLimitN = speedFactor
    * rawInputs.motorRegenPowerLimitKw
    * 1000
    / safeSpeedMps;

  const socFactor = clamp(
    (calibration.socStopPct - batterySocPct)
      / (calibration.socStopPct - calibration.socDeratePct),
    0,
    1,
  );

  const coldFactor = clamp(
    (rawInputs.batteryTempC - calibration.coldCutoffC)
      / (calibration.coldFullC - calibration.coldCutoffC),
    0,
    1,
  );
  const hotFactor = clamp(
    (calibration.hotCutoffC - rawInputs.batteryTempC)
      / (calibration.hotCutoffC - calibration.hotFullC),
    0,
    1,
  );
  const temperatureFactor = Math.min(coldFactor, hotFactor);

  const currentDerivedChargePowerKw = rawInputs.batteryVoltageV
    * rawInputs.chargeCurrentLimitA
    / 1000;
  const baseChargePowerKw = Math.min(
    rawInputs.chargePowerLimitKw,
    currentDerivedChargePowerKw,
  );
  const allowedBatteryPowerKw = baseChargePowerKw * socFactor * temperatureFactor;
  const batteryForceLimitN = allowedBatteryPowerKw
    * 1000
    / (calibration.regenEfficiency * safeSpeedMps);

  const minimumAllowedForceN = Math.min(
    requestedForceN,
    torqueForceLimitN,
    powerForceLimitN,
    batteryForceLimitN,
  );
  const regenerativeForceN = enableFactor * Math.max(0, minimumAllowedForceN);
  const frictionForceN = Math.max(0, requestedForceN - regenerativeForceN);

  const regenerativeWheelTorqueNm = regenerativeForceN * calibration.wheelRadiusM;
  const frictionWheelTorqueNm = frictionForceN * calibration.wheelRadiusM;
  const mechanicalRegenPowerKw = regenerativeForceN * vehicleSpeedMps / 1000;
  const batteryChargePowerKw = Math.min(
    mechanicalRegenPowerKw * calibration.regenEfficiency,
    allowedBatteryPowerKw,
  );
  const regenerativeCurrentA = batteryChargePowerKw * 1000 / rawInputs.batteryVoltageV;

  const safeRequestedForceN = Math.max(requestedForceN, calibration.forceEpsilonN);
  const regenerativePercent = 100 * regenerativeForceN / safeRequestedForceN;
  const frictionPercent = 100 * frictionForceN / safeRequestedForceN;
  const forceBalanceResidualN = requestedForceN - regenerativeForceN - frictionForceN;

  let activeLimitCode: ActiveLimitCode = "DRIVER_DEMAND";
  let activeLimitLabel = "Driver braking demand";
  const tolerance = 1e-7;

  if (requestedForceN <= calibration.forceEpsilonN) {
    activeLimitCode = "NO_BRAKING";
    activeLimitLabel = "No braking requested";
  } else if (enableFactor <= tolerance) {
    activeLimitCode = "REGEN_DISABLED";
    activeLimitLabel = "Regenerative braking disabled";
  } else if (speedFactor <= tolerance) {
    activeLimitCode = "LOW_SPEED";
    activeLimitLabel = "Low-speed regenerative cut-off";
  } else if (socFactor <= tolerance) {
    activeLimitCode = "BATTERY_SOC";
    activeLimitLabel = "Battery state-of-charge limit";
  } else if (temperatureFactor <= tolerance) {
    activeLimitCode = "BATTERY_TEMPERATURE";
    activeLimitLabel = "Battery temperature limit";
  } else {
    const candidates = [
      ["DRIVER_DEMAND", requestedForceN] as const,
      ["MOTOR_TORQUE", torqueForceLimitN] as const,
      ["MOTOR_POWER", powerForceLimitN] as const,
      ["BATTERY_ACCEPTANCE", batteryForceLimitN] as const,
    ];
    candidates.sort((a, b) => a[1] - b[1]);
    activeLimitCode = candidates[0][0];

    if (activeLimitCode === "DRIVER_DEMAND") {
      activeLimitLabel = "Driver braking demand";
    } else if (activeLimitCode === "MOTOR_TORQUE") {
      activeLimitLabel = "Motor regenerative-torque limit";
    } else if (activeLimitCode === "MOTOR_POWER") {
      activeLimitLabel = "Motor regenerative-power limit";
    } else {
      if (socFactor < 1 - tolerance && socFactor <= temperatureFactor + tolerance) {
        activeLimitCode = "BATTERY_SOC";
        activeLimitLabel = "Battery state-of-charge limit";
      } else if (temperatureFactor < 1 - tolerance) {
        activeLimitCode = "BATTERY_TEMPERATURE";
        activeLimitLabel = "Battery temperature limit";
      } else if (currentDerivedChargePowerKw <= rawInputs.chargePowerLimitKw + tolerance) {
        activeLimitCode = "BATTERY_CURRENT";
        activeLimitLabel = "Battery charging-current limit";
      } else {
        activeLimitCode = "BATTERY_POWER";
        activeLimitLabel = "Battery charging-power limit";
      }
    }
  }

  const stopTimeEstimateS = requestedDecelerationMps2 > 0
    ? vehicleSpeedMps / requestedDecelerationMps2
    : 0;
  const stopDistanceEstimateM = requestedDecelerationMps2 > 0
    ? vehicleSpeedMps ** 2 / (2 * requestedDecelerationMps2)
    : 0;
  const animationDurationS = stopTimeEstimateS > 0
    ? clamp(stopTimeEstimateS, 1, 8)
    : 0;

  return {
    requestedDecelerationMps2,
    requestedForceN,
    requestedWheelTorqueNm,
    vehicleSpeedMps,
    wheelSpeedRpm,
    motorSpeedRpm,
    speedFactor,
    socFactor,
    temperatureFactor,
    currentDerivedChargePowerKw,
    baseChargePowerKw,
    allowedBatteryPowerKw,
    torqueForceLimitN,
    powerForceLimitN,
    batteryForceLimitN,
    regenerativeForceN,
    frictionForceN,
    regenerativeWheelTorqueNm,
    frictionWheelTorqueNm,
    mechanicalRegenPowerKw,
    batteryChargePowerKw,
    regenerativeCurrentA,
    regenerativePercent,
    frictionPercent,
    forceBalanceResidualN,
    activeLimitCode,
    activeLimitLabel,
    warnings,
    visual: {
      stopTimeEstimateS,
      stopDistanceEstimateM,
      animationDurationS,
      regenIntensity01: clamp(regenerativePercent / 100, 0, 1),
      frictionHeatIntensity01: clamp(frictionPercent / 100, 0, 1),
      batteryChargeIntensity01: baseChargePowerKw > 0
        ? clamp(batteryChargePowerKw / baseChargePowerKw, 0, 1)
        : 0,
    },
  };
}
